def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_bands = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_bands.append(range(start, r))
        start = r + 1
    if start < h:
        row_bands.append(range(start, h))

    col_bands = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_bands.append(range(start, c))
        start = c + 1
    if start < w:
        col_bands.append(range(start, w))

    separators = set(sep_rows)
    separator_color = grid[sep_rows[0]][0] if sep_rows else None
    interior = [
        grid[r][c]
        for r in range(h) if r not in separators
        for c in range(w) if c not in set(sep_cols)
        and grid[r][c] != separator_color
    ]
    background = max(set(interior), key=interior.count)

    out = []
    for rows in row_bands:
        out_row = []
        for cols in col_bands:
            count = sum(grid[r][c] != background for r in rows for c in cols)
            out_row.append(1 if count == 2 else background)
        out.append(out_row)
    return out
